'use client'

import React from 'react'
import Link from 'next/link'
import { usePathname } from 'next/navigation'
import { 
  BarChart3, 
  Building2, 
  ClipboardCheck, 
  History, 
  LayoutDashboard, 
  Package, 
  Settings, 
  Stethoscope, 
  Users, 
  WalletCards 
} from 'lucide-react'

const navItems = [
  { name: 'Dashboard', icon: LayoutDashboard, path: '/', role: ['SUPER_ADMIN', 'ADMIN', 'PHARMACIST', 'DOCTOR', 'HR_MANAGER', 'ACCOUNTANT'] },
  { name: 'Branches', icon: Building2, path: '/branches', role: ['SUPER_ADMIN'] },
  { name: 'Inventory', icon: Package, path: '/products', role: ['SUPER_ADMIN', 'ADMIN', 'PHARMACIST'] },
  { name: 'HR Management', icon: Users, path: '/hr', role: ['SUPER_ADMIN', 'ADMIN', 'HR_MANAGER'] },
  { name: 'Clinic', icon: Stethoscope, path: '/clinic', role: ['SUPER_ADMIN', 'ADMIN', 'DOCTOR'] },
  { name: 'Accounts', icon: WalletCards, path: '/finance', role: ['SUPER_ADMIN', 'ADMIN', 'ACCOUNTANT'] },
  { name: 'Reports', icon: BarChart3, path: '/reports', role: ['SUPER_ADMIN', 'ADMIN', 'ACCOUNTANT'] },
  { name: 'Audit Logs', icon: History, path: '/settings/audit', role: ['SUPER_ADMIN'] },
]

export function Sidebar({ userRole = 'PHARMACIST', isOpen, setOpen }: { userRole?: string, isOpen?: boolean, setOpen?: (val: boolean) => void }) {
  const pathname = usePathname()

  const filteredItems = navItems.filter(item => item.role.includes(userRole || 'PHARMACIST'))

  return (
    <div className={`fixed inset-y-0 left-0 z-40 w-64 bg-slate-900 text-slate-100 flex flex-col border-r border-slate-800 shadow-xl transition-transform duration-300 lg:translate-x-0 ${isOpen ? 'translate-x-0' : '-translate-x-full'}`}>
      <div className="flex items-center justify-between px-6 py-8 border-b border-slate-800/50">
        <div className="flex items-center gap-3">
          <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-blue-600 shadow-blue-500/20 shadow-lg">
            <Stethoscope className="h-6 w-6 text-white" />
          </div>
          <div>
            <h1 className="text-xl font-bold tracking-tight text-white">JailWatch <span className="text-blue-500">Pro</span></h1>
            <p className="text-[10px] text-slate-400 font-medium uppercase tracking-[0.1em]">Hospital Chain SaaS</p>
          </div>
        </div>
        {setOpen && (
          <button onClick={() => setOpen(false)} className="lg:hidden text-slate-400 hover:text-white">
            <Settings className="h-5 w-5" />
          </button>
        )}
      </div>

      <nav className="flex-1 space-y-1.5 px-4 py-8 overflow-y-auto">
        {filteredItems.map((item) => {
          const isActive = pathname === item.path
          const Icon = item.icon
          
          return (
            <Link
              key={item.name}
              href={item.path}
              className={`flex items-center gap-3 rounded-lg px-4 py-3 text-sm font-medium transition-all duration-200 group relative
                ${isActive 
                  ? 'bg-blue-600 text-white shadow-md shadow-blue-600/20' 
                  : 'text-slate-400 hover:bg-slate-800/50 hover:text-white'
                }`}
            >
              {isActive && (
                <div className="absolute left-0 top-1/2 -translate-y-1/2 h-6 w-1 rounded-r bg-white" />
              )}
              <Icon className={`h-5 w-5 ${isActive ? 'text-white' : 'text-slate-500 group-hover:text-blue-400'}`} />
              {item.name}
            </Link>
          )
        })}
      </nav>

      <div className="p-6 border-t border-slate-800/50">
        <div className="flex items-center gap-3 rounded-xl bg-slate-800/30 p-3 hover:bg-slate-800/50 transition-colors cursor-pointer group">
          <div className="h-10 w-10 rounded-full bg-slate-700 flex items-center justify-center border border-slate-600 overflow-hidden">
             <div className="bg-gradient-to-tr from-blue-600 to-indigo-600 h-full w-full flex items-center justify-center text-xs font-bold text-white uppercase italic">
              {(userRole || 'PH').slice(0, 2)}
             </div>
          </div>
          <div className="flex-1 overflow-hidden">
            <p className="text-sm font-semibold truncate text-white">{userRole || 'Pharmacist'}</p>
            <p className="text-[10px] text-slate-500 truncate font-medium">System Role</p>
          </div>
          <Settings className="h-4 w-4 text-slate-500 group-hover:text-white transition-colors" />
        </div>
      </div>
    </div>
  )
}

